def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    lines=set()
    for i,(r,c) in enumerate(pts):
        for rr,cc in pts[i+1:]:
            if r==rr:
                for x in range(min(c,cc),max(c,cc)+1): lines.add((r,x))
            if c==cc:
                for x in range(min(r,rr),max(r,rr)+1): lines.add((x,c))
    for r,c in lines: out[r][c]=1
    # Any 2-component touched by a marker line is recolored entirely.
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        comp=[]; stack=[(r,c)]; seen.add((r,c))
        while stack:
          x,y=stack.pop(); comp.append((x,y))
          for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
              seen.add((a,b)); stack.append((a,b))
        if any(p in lines for p in comp):
          for x,y in comp: out[x][y]=1
    return out
